import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for AssignSubflowOutputs validation - empty values object
 * Should fail: Values object cannot be empty
 */
export const assignSubflowOutputsEmptyValues = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-empty-values'],
        name: 'AssignSubflowOutputs Empty Values Test',
        description: 'Test AssignSubflowOutputs validation with empty values object',
        inputs: {
            inputData: StringColumn({
                label: 'Input Data',
                mandatory: true,
            }),
        },
        outputs: {
            result: StringColumn({
                label: 'Result',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // This should fail validation: empty values object
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-empty'],
                annotation: 'Invalid: empty values',
            },
            params.outputs,
            {} // Empty object - should fail
        )
    }
)
